mkdir -p /tmp/pw/shots && cat > /tmp/pw/check.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1360, height: 900 } });
const errors = [];
p.on('console', m => { if (m.type()==='error'||m.type()==='warning') errors.push(m.text()); });
p.on('pageerror', e => errors.push('PAGEERR ' + e.message));
await p.goto('http://localhost:5199/');
await p.waitForSelector('.card');
await p.waitForTimeout(400);
await p.screenshot({ path: '/tmp/pw/shots/1-initial.png', fullPage: true });

const rect = async (title) => p.locator(`section[aria-label="${title}"]`).locator('xpath=..').evaluate(el => {
  const r = el.getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)];
});
console.log('revenue before', await rect('Выручка'), 'traffic', await rect('Посетители'));

// Drag "Посетители" header to the right over the KPI row
const h = p.locator('section[aria-label="Посетители"] .card__handle');
const hb = await h.boundingBox();
await p.mouse.move(hb.x + 60, hb.y + 15);
await p.mouse.down();
await p.mouse.move(hb.x + 300, hb.y - 80, { steps: 8 });
await p.mouse.move(hb.x + 500, hb.y - 200, { steps: 8 });
await p.screenshot({ path: '/tmp/pw/shots/2-dragging.png', fullPage: true });
await p.mouse.up();
await p.waitForTimeout(400);
await p.screenshot({ path: '/tmp/pw/shots/3-dropped.png', fullPage: true });
console.log('after drag traffic', await rect('Посетители'), 'revenue', await rect('Выручка'));

// Resize "Выручка по каналам"
const rz = p.locator('section[aria-label="Выручка по каналам"]').locator('xpath=..').locator('.grid__resize');
const rb = await rz.boundingBox();
console.log('channels before', await rect('Выручка по каналам'));
await p.mouse.move(rb.x + 10, rb.y + 10);
await p.mouse.down();
await p.mouse.move(rb.x - 150, rb.y + 120, { steps: 8 });
await p.mouse.up();
await p.waitForTimeout(400);
console.log('channels after', await rect('Выручка по каналам'));
await p.screenshot({ path: '/tmp/pw/shots/4-resized.png', fullPage: true });

// Reload: persisted?
const before = await rect('Посетители');
await p.reload(); await p.waitForSelector('.card'); await p.waitForTimeout(400);
console.log('persisted', JSON.stringify(before) === JSON.stringify(await rect('Посетители')));

// Remove + add
await p.getByRole('button', { name: /Убрать виджет «Конверсия»/ }).click();
console.log('cards after remove', await p.locator('.card').count());
await p.getByRole('button', { name: 'Добавить виджет' }).click();
await p.waitForTimeout(200);
await p.screenshot({ path: '/tmp/pw/shots/5-menu.png' });
await p.getByRole('menuitem', { name: 'Конверсия' }).click();
await p.waitForTimeout(400);
console.log('cards after add', await p.locator('.card').count());

// Hover tooltip on line chart
const plot = await p.locator('.chart__plot svg').boundingBox();
await p.mouse.move(plot.x + plot.width * 0.5, plot.y + plot.height * 0.5);
await p.waitForTimeout(150);
await p.screenshot({ path: '/tmp/pw/shots/6-hover.png', fullPage: true });

// Keyboard move
const kh = p.locator('section[aria-label="Заказы"] .card__handle');
const kb = await rect('Заказы');
await kh.focus(); await p.keyboard.press('ArrowRight'); await p.waitForTimeout(350);
console.log('kbd move', kb, '->', await rect('Заказы'));
console.log('ERRORS', errors);
await b.close();
EOF
cd /tmp/pw && node check.mjs

